var CAR_SOUNDS = {"car_door": "data:audio/wav;base64,", "engine_accel": "data:audio/wav;base64,", "engine_idle": "data:audio/wav;base64,", "engine_start": "data:audio/wav;base64,", "engine_stop": "data:audio/wav;base64,"};


