  var _ringCtx = null, _ringTimer = null, _ringOsc = [];
  function stopIPhoneRing() {
    if (_ringTimer) { clearInterval(_ringTimer); _ringTimer = null; }
    _ringOsc.forEach(function (o) { try { o.stop(); } catch (e) {} });
    _ringOsc = [];
  }
  function playIPhoneRing() {
    stopIPhoneRing();
    try {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      if (!_ringCtx) _ringCtx = new AC();
      var ctx = _ringCtx;
      if (ctx.state === 'suspended') ctx.resume();
      // نمط رنة الآيفون الكلاسيكية (نغمتين متكررتين)
      function beepPair() {
        var now = ctx.currentTime;
        [0, 0.2].forEach(function (off, i) {
          var osc = ctx.createOscillator();
          var gain = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.value = i === 0 ? 1200 : 1000;
          gain.gain.setValueAtTime(0.0001, now + off);
          gain.gain.exponentialRampToValueAtTime(0.25, now + off + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.0001, now + off + 0.18);
          osc.connect(gain); gain.connect(ctx.destination);
          osc.start(now + off);
          osc.stop(now + off + 0.2);
          _ringOsc.push(osc);
        });
      }
      beepPair();
      _ringTimer = setInterval(beepPair, 1200);
    } catch (e) { console.warn('ring', e); }
  }

  function showIncomingCall(fromName, isAdd) {
    ensureCallUI();
    phoneState.ringing = true;
    document.getElementById('call-from-name').textContent = fromName || 'رقم مجهول';
    var sub = document.getElementById('call-sub');
    if (sub) sub.textContent = isAdd ? 'إضافة إلى المكالمة...' : 'iPhone · اتصال وارد';
    phoneCallUI.style.display = 'block';
    playIPhoneRing();
    document.getElementById('call-accept').onclick = function () {
      stopIPhoneRing();
      enableLocalMic();
      phoneCallUI.style.display = 'none';
      phoneState.ringing = false;
      acceptCall(fromName);
    };
    document.getElementById('call-reject').onclick = function () {
      stopIPhoneRing();
      phoneCallUI.style.display = 'none';
      phoneState.ringing = false;
      try { if (Game.netSend) Game.netSend({ kind: 'phone', action: 'reject', from: phoneState.myName || getLocalPlayerName(), to: fromName }); } catch (e) {}
      Game.toast('تم رفض المكالمة', 'info');
    };
  }
  function startCall(targetName, isAdd, targetId) {
    phoneState.myName = getLocalPlayerName();
    phoneState.myId = getLocalNetId();
    if (namesMatch(targetName, phoneState.myName)) { Game.toast('مينفعش ترن على نفسك', 'info'); return; }
    try { enableLocalMic(); } catch (ePre) {}
    try {
      if (Game.netSend) {
        Game.netSend({
          kind: 'phone',
          action: isAdd ? 'add' : 'invite',
          from: phoneState.myName,
          fromId: phoneState.myId,
          to: targetName,
          toId: targetId || null,
          peers: phoneState.peers.slice()
        });
      }
    } catch (e) {}
    var st = document.getElementById('phone-status');
    if (st) st.textContent = 'جاري الرنين على ' + targetName + '...';
    Game.toast('📞 رنين على ' + targetName, 'info');
  }
  function acceptCall(fromName) {
    if (!phoneState.myName) phoneState.myName = getLocalPlayerName();
    if (phoneState.peers.indexOf(fromName) < 0) phoneState.peers.push(fromName);
    phoneState.inCall = true;
    try {
      if (Game.netSend) {
        Game.netSend({ kind: 'phone', action: 'accept', from: phoneState.myName, fromId: phoneState.myId || getLocalNetId(), to: fromName, peers: phoneState.peers.slice() });
      }
    } catch (e) {}
    enableLocalMic();
    Game.toast('تم قبول المكالمة مع ' + fromName, 'success');
    openPhone();
    refreshPeersList();
  }
  function endCall(notify) {
    try { stopIPhoneRing(); } catch (eR) {}
    phoneState.inCall = false;
    var oldPeers = phoneState.peers.slice();
    phoneState.peers = [];
    disableLocalMic();
    if (notify) {
      try {
        if (Game.netSend) {
          oldPeers.forEach(function (p) {
            Game.netSend({ kind: 'phone', action: 'end', from: phoneState.myName || getLocalPlayerName(), to: p });
          });
        }
      } catch (e) {}
      Game.toast('انتهت المكالمة', 'info');
    }
    if (phoneUI) {
      var ic = document.getElementById('phone-in-call');
      if (ic) ic.style.display = 'none';
      var st = document.getElementById('phone-status');
      if (st) st.textContent = 'جاهز للاتصال';
    }
    if (phoneCallUI) phoneCallUI.style.display = 'none';
    phoneState.ringing = false;
  }
  function enableLocalMic() {
    if (localMicStream) {
      // تأكد إن التراكات شغالة
      try {
        localMicStream.getTracks().forEach(function (t) { if (t.readyState === 'live') t.enabled = true; });
      } catch (e0) {}
      return;
    }
    function onOk(stream) {
      localMicStream = stream;
      try {
        stream.getAudioTracks().forEach(function (t) { t.enabled = true; });
      } catch (e1) {}
      Game.toast('المايك مفعّل — اتكلم', 'success');
    }
    function onFail(err) {
      console.warn('mic fail', err);
      var msg = 'اسمح بالمايك من شريط المتصفح (القفل بجانب الرابط)';
      if (err && err.name === 'NotAllowedError') msg = 'تم رفض المايك — اضغط القفل 🔒 جنب الرابط واسمح بالمايك';
      if (err && err.name === 'NotFoundError') msg = 'مفيش مايك متصل بالجهاز';
      Game.toast(msg, 'error');
    }
    try {
      var md = navigator.mediaDevices;
      if (md && md.getUserMedia) {
        // طلب صريح لإذن المايك (Chrome/Edge/Firefox)
        md.getUserMedia({
          audio: {
            echoCancellation: true,
            noiseSuppression: true,
            autoGainControl: true
          },
          video: false
        }).then(onOk).catch(function (err) {
          // محاولة أبسط لو الإعدادات المتقدمة فشلت
          md.getUserMedia({ audio: true, video: false }).then(onOk).catch(onFail);
        });
        return;
      }
      // متصفحات قديمة
      var legacy = navigator.getUserMedia || navigator.webkitGetUserMedia || navigator.mozGetUserMedia;
      if (legacy) {
        legacy.call(navigator, { audio: true }, onOk, onFail);
        return;
      }
      Game.toast('المتصفح لا يدعم المايك', 'error');
    } catch (e) {
      onFail(e);
    }
  }
  function disableLocalMic() {
    if (localMicStream) {
      try { localMicStream.getTracks().forEach(function (t) { t.stop(); }); } catch (e) {}
      localMicStream = null;
    }
  }
  function handlePhoneNet(data) {
    if (!data || data.kind !== 'phone') return;
    phoneState.myName = getLocalPlayerName();
    phoneState.myId = getLocalNetId();
    var me = phoneState.myName;
    var meId = phoneState.myId;
    function isForMe() {
      if (data.toId && meId && data.toId === meId) return true;
      if (data.to && namesMatch(data.to, me)) return true;
      return false;
    }
    if (data.action === 'invite' || data.action === 'add') {
      if (isForMe()) showIncomingCall(data.from, data.action === 'add');
    } else if (data.action === 'accept') {
      if (isForMe() || phoneState.peers.indexOf(data.from) >= 0 || !phoneState.inCall) {
        if (phoneState.peers.indexOf(data.from) < 0) phoneState.peers.push(data.from);
        if (data.peers) {
          data.peers.forEach(function (p) {
            if (p !== me && phoneState.peers.indexOf(p) < 0) phoneState.peers.push(p);
          });
        }
        phoneState.inCall = true;
        enableLocalMic();
        Game.toast(data.from + ' قبل المكالمة', 'success');
        if (phoneUI && phoneUI.style.display === 'flex') {
          var ic = document.getElementById('phone-in-call');
          if (ic) ic.style.display = 'block';
          refreshPeersList();
        }
      }
    } else if (data.action === 'reject') {
      if (isForMe() || (data.to && namesMatch(data.to, me))) {
        Game.toast(data.from + ' رفض المكالمة', 'info');
        var st = document.getElementById('phone-status');
        if (st) st.textContent = data.from + ' رفض';
      }
    } else if (data.action === 'end') {
      if (data.to === me || phoneState.peers.indexOf(data.from) >= 0) {
        var idx = phoneState.peers.indexOf(data.from);
        if (idx >= 0) phoneState.peers.splice(idx, 1);
        Game.toast(data.from + ' خرج من المكالمة', 'info');
        if (!phoneState.peers.length) endCall(false);
        else refreshPeersList();
      }
    }
  }



  // ========== تزامن للاعبين الجدد ==========
  var syncReqAcc = 0, fullSyncAcc = 0;
  var _lastSyncHash = '';
  function broadcastFullState() {
    if (!Game.netSend || !carsSpawned) return;
    try {
      var payload = { kind: 'sync_state', cars: [], music: null };
      for (var i = 0; i < cars.length; i++) {
        var car = cars[i];
        var s = car.userData.seats || {};
        // seats كسلسلة قصيرة بدل object كبير
        var seatBits = (s.driver != null ? 1 : 0) | (s.front != null ? 2 : 0) | (s.rear_l != null ? 4 : 0) | (s.rear_r != null ? 8 : 0);
        payload.cars.push({
          n: car.userData.instanceName,
          x: Math.round(car.position.x * 50) / 50,
          z: Math.round(car.position.z * 50) / 50,
          y: Math.round(car.rotation.y * 100) / 100,
          e: car.userData.engineOn ? 1 : 0,
          s: seatBits
        });
      }
      if (musicPlaying) payload.music = { n: musicPlaying.name, c: musicPlaying.carName || '' };
      var hash = JSON.stringify(payload);
      if (hash === _lastSyncHash) return; // مفيش تغيير
      _lastSyncHash = hash;
      Game.netSend(payload);
    } catch (e) {}
  }
  function applySyncState(data) {
    if (!data || !data.cars) return;
    if (!carsSpawned) spawnCars();
    data.cars.forEach(function (s) {
      var name = s.n || s.name;
      var car = findCar(name);
      if (!car) return;
      var mine = false;
      for (var bk in localBoarded) {
        if (localBoarded[bk] && localBoarded[bk].seat === 'driver' && localBoarded[bk].carName === name) mine = true;
      }
      if (!mine) {
        var nx = s.x, nz = s.z, ny = (s.y != null ? s.y : s.yaw);
        // تحريك ناعم بسيط لتقليل الرجفة
        car.position.x += (nx - car.position.x) * 0.55;
        car.position.z += (nz - car.position.z) * 0.55;
        car.rotation.y = ny;
        car.userData.engineOn = !!(s.e != null ? s.e : s.engine);
      }
      var bits = s.s;
      if (bits == null && s.seats) {
        bits = (s.seats.driver ? 1 : 0) | (s.seats.front ? 2 : 0) | (s.seats.rear_l ? 4 : 0) | (s.seats.rear_r ? 8 : 0);
      }
      if (bits != null) {
        car.userData.seats = car.userData.seats || { driver: null, front: null, rear_l: null, rear_r: null };
        var map = [['driver', 1], ['front', 2], ['rear_l', 4], ['rear_r', 8]];
        for (var mi = 0; mi < map.length; mi++) {
          var seat = map[mi][0], bit = map[mi][1];
          if ((bits & bit) && car.userData.seats[seat] == null) car.userData.seats[seat] = 'remote';
          if (!(bits & bit) && car.userData.seats[seat] === 'remote') car.userData.seats[seat] = null;
        }
      }
    });
    var mus = data.music;
    if (mus) {
      var mname = mus.n || mus.name;
      if (mname) {
        if (!musicPlaying || musicPlaying.name !== mname) startMusic(mname, true);
        if (musicPlaying) musicPlaying.carName = mus.c || mus.car;
      }
    }
  }

    if (Game.onNet) {
      Game.onNet(function (data) {
        if (!data || !data.kind) return;
        if (data.kind === 'phone') { handlePhoneNet(data); return; }
        if (data.kind === 'sync_request') { broadcastFullState(); return; }
        if (data.kind === 'sync_state') { applySyncState(data); return; }
        if (data.kind === 'car_sfx' && data.sfx) {
          var v = volumeAtCar(data.car, 55, 0.65);
          if (v > 0.02) playSfx(data.sfx, v);
        }
        if (data.kind === 'car_music') {
          if (data.on && data.name) {
            if (!musicPlaying || musicPlaying.name !== data.name) startMusic(data.name, true);
            if (musicPlaying) musicPlaying.carName = data.car;
          } else {
            stopMusic(false);
          }
        }
        if (data.kind === 'seat' && data.car) {
          var c = findCar(data.car); if (!c) return;
          c.userData.seats = c.userData.seats || { driver: null, front: null, rear_l: null, rear_r: null };
          if (data.taken) c.userData.seats[data.seat] = 'remote';
          else if (c.userData.seats[data.seat] === 'remote') c.userData.seats[data.seat] = null;
        }
        if (data.kind === 'car_pose' && data.name) {
          if (!carsSpawned) spawnCars();
          // لا تحرّك عربية أنا بسوقها
          var mine = false;
          for (var bk in localBoarded) {
            if (localBoarded[bk] && localBoarded[bk].seat === 'driver' && localBoarded[bk].carName === data.name) mine = true;
          }
          if (mine) return;
          var car = findCar(data.name); if (!car) return;
          // تحريك ناعم لتقليل الرجفة على الشبكة
          car.position.x += (data.x - car.position.x) * 0.6;
          car.position.z += (data.z - car.position.z) * 0.6;
          var dy = data.yaw - car.rotation.y;
          while (dy > Math.PI) dy -= Math.PI * 2;
          while (dy < -Math.PI) dy += Math.PI * 2;
          car.rotation.y += dy * 0.6;
          car.userData.engineOn = !!data.engine;
          if (data.speed != null) car.userData.speed = data.speed;
          // الراكب المحلي يلزق فوراً بعد تحريك العربية من الشبكة
          for (var pk in localBoarded) {
            if (!localBoarded.hasOwnProperty(pk)) continue;
            var bi = localBoarded[pk];
            if (bi && bi.carName === data.name) {
              bi.car = car;
              stickSeat(parseInt(pk, 10), car, bi.seat);
            }
          }
        }
      });
    }

